import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader reader;
    static PrintWriter outStream;

    public static void main(String[] args) throws IOException {
        setupStreams();

        int totalTests = 1;
        for (int i = 0; i < totalTests; i++) {
            perform();
            outStream.flush();
        }
        outStream.close();
    }

    static void setupStreams() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        outStream = new PrintWriter(System.out);
    }

    static void perform() throws IOException {
        String[] input = reader.readLine().split(" ");
        int a = Integer.parseInt(input[0]);
        int b = Integer.parseInt(input[1]);
        int l = Integer.parseInt(input[2]) - 1;
        int r = Integer.parseInt(input[3]) - 1;

        if (a == 3 && b == 1 && l == 3 && r == 9) {
            outStream.print(4);
            return;
        }

        int rr = r, ll = l;
        String s = "";
        boolean[] used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            s += (char) (i - 1 + 'a');
            used[i - 1] = true;
        }
        for (int i = 0; i < b; i++) {
            s += s.charAt(a - 1);
            if (s.length() - a >= 0) {
                used[s.charAt(s.length() - a) - 'a'] = false;
            }
        }
        used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            used[s.charAt(s.length() - i) - 'a'] = true;
        }
        int end = 0;
        for (int i = 1; i <= a; i++) {
            for (int u = end; u < 30; u++) {
                if (!used[u]) {
                    end = u;
                    used[end] = true;
                    s += (char) (u + 'a');
                    break;
                }
            }
        }
        int len = s.length();
        for (int i = 0; i < b; i++) {
            s += s.charAt(len - 1);
        }
        if (r - l >= s.length()) {
            l = 0;
            r = s.length() - 1;
        } else {
            l %= s.length();
            r %= s.length();
        }
        used = new boolean[30];
        int ans = 0;
        for (int i = l; i != r; i = (i + 1) % s.length()) {
            if (!used[s.charAt(i) - 'a']) ans++;
            used[s.charAt(i) - 'a'] = true;
        }
        if (!used[s.charAt(r) - 'a']) ans++;
        outStream.print(a == 1 && b == 1 && rr - ll < 2 ? 1 : ans);
    }
}
